      "id": "SG-osaka-blocks-encode-receipt",
      "name": "Receipt Encoding Function",
      "description": "Encodes a transaction receipt based on the transaction type. The encoding follows the same format as transaction encoding, where typed transactions prefix their receipt with a type byte (0x01 for AccessList, 0x02 for FeeMarket, 0x03 for Blob, 0x04 for SetCode) and RLP-encode the body, while legacy transactions return the receipt as-is.",
      "invariants": [
        {
          "id": "INV-osaka-blocks-022",
          "text": "Receipt encoding type prefix must match the transaction type: 0x01=AccessList, 0x02=FeeMarket, 0x03=Blob, 0x04=SetCode."
        },
        {
          "id": "INV-osaka-blocks-023",
          "text": "Legacy transaction receipts are returned without any prefix or additional encoding."
        },
        {
          "id": "INV-osaka-blocks-024",
          "text": "encode_receipt and decode_receipt are inverse operations: decode_receipt(encode_receipt(tx, receipt)) == receipt for all valid tx and receipt."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-osaka-blocks-001",
          "text": "The tx parameter must be a valid Transaction type (one of LegacyTransaction, AccessListTransaction, FeeMarketTransaction, BlobTransaction, SetCodeTransaction)."
        },
        {
          "id": "PRE-osaka-blocks-002",
          "text": "The receipt parameter must be a valid Receipt instance."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-osaka-blocks-001",
          "text": "For typed transactions, the return value is a Bytes object with the type prefix byte followed by the RLP-encoded receipt."
        },
        {
          "id": "POST-osaka-blocks-002",
          "text": "For legacy transactions, the return value is the Receipt object unchanged."
        }
      ],
      "state_transitions": [],
      "functions": [
        {
          "id": "FN-osaka-blocks-001",
          "name": "encode_receipt",
          "signature": "def encode_receipt(tx: Transaction, receipt: Receipt) -> Bytes | Receipt",
          "description": "Encodes a transaction receipt based on the transaction type. Typed transactions get a prefix byte + RLP encoding; legacy receipts are returned as-is.",
          "parameters": [
            {
              "name": "tx",
              "type": "Transaction",
              "description": "The transaction whose type determines the encoding scheme."
            },
            {
              "name": "receipt",
              "type": "Receipt",
              "description": "The receipt to encode."
            }
          ],
          "return_type": "Bytes | Receipt",
          "logic": [
            "If tx is AccessListTransaction: return b'\\x01' + rlp.encode(receipt)",
            "If tx is FeeMarketTransaction: return b'\\x02' + rlp.encode(receipt)",
            "If tx is BlobTransaction: return b'\\x03' + rlp.encode(receipt)",
            "If tx is SetCodeTransaction: return b'\\x04' + rlp.encode(receipt)",
            "Otherwise (LegacyTransaction): return receipt as-is"
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
