    {
      "id": "SG-osaka-blocks-decode-receipt",
      "name": "Receipt Decoding Function",
      "description": "Decodes a receipt from its serialized form. Typed receipts (prefixed with a type byte 0x01-0x04) are stripped of their prefix and RLP-decoded. Legacy receipts (Receipt objects) are returned as-is.",
      "invariants": [
        {
          "id": "INV-osaka-blocks-025",
          "text": "Only type prefix bytes 1, 2, 3, and 4 are valid for Bytes receipts; any other prefix triggers an assertion error."
        },
        {
          "id": "INV-osaka-blocks-026",
          "text": "decode_receipt is the inverse of encode_receipt: for any valid (tx, receipt) pair, decode_receipt(encode_receipt(tx, receipt)) == receipt."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-osaka-blocks-003",
          "text": "If receipt is Bytes, its first byte must be one of {1, 2, 3, 4} (assertion enforced)."
        },
        {
          "id": "PRE-osaka-blocks-004",
          "text": "If receipt is Bytes, the remaining bytes (receipt[1:]) must be valid RLP-encoded Receipt data."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-osaka-blocks-003",
          "text": "The return value is always a Receipt instance."
        }
      ],
      "state_transitions": [],
      "functions": [
        {
          "id": "FN-osaka-blocks-002",
          "name": "decode_receipt",
          "signature": "def decode_receipt(receipt: Bytes | Receipt) -> Receipt",
          "description": "Decodes a receipt from its serialized form. Strips type prefix byte and RLP-decodes for typed transactions; returns Receipt as-is for legacy.",
          "parameters": [
            {
              "name": "receipt",
              "type": "Bytes | Receipt",
              "description": "The encoded receipt to decode, either raw bytes with type prefix or a Receipt object."
            }
          ],
          "return_type": "Receipt",
          "logic": [
            "If receipt is Bytes: assert receipt[0] in (1, 2, 3, 4), then return rlp.decode_to(Receipt, receipt[1:])",
            "Otherwise (Receipt object): return receipt as-is"
          ]
        }
      ],
